import java.util.*;

class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int lo = 1, hi = 1;
        for (int p : piles) hi = Math.max(hi, p);  // pace max(piles) always works
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (hoursNeeded(piles, mid) <= h) hi = mid; // fast enough, try slower
            else lo = mid + 1;                          // too slow
        }
        return lo;
    }

    private long hoursNeeded(int[] piles, int s) {
        long hours = 0;
        for (int p : piles) hours += (p + (long) s - 1) / s; // ceil(p / s)
        return hours;
    }
}

